```javascript
const text = input.text;
if (text.startsWith('```') && text.endsWith('```')) {
    const codeBlock = text.slice(1, -1);
    if (!codeBlock.match(/^\s*{.*\}$/)) throw new Error("Invalid JSON");
    return JSON.stringify(JSON.parse(codeBlock), null, 2);
} else if (text.includes('\n\n') || text.includes('\r\n\r\n')) {
    const lines = text.split('\n');
    let jsonStr = "";
    for (let i = 0; i < lines.length; i++) {
        if (lines[i].trim().startsWith('{') && lines[i].trim().endsWith('}') && !jsonStr) {
            jsonStr += lines[i];
        } else {
            jsonStr += '\n' + lines[i];
        }
    }
    return JSON.stringify(jsonStr, null, 2);
} else {
    throw new Error("Invalid JSON");
}
```

